class Solution {
    public long findMaximumElegance(int[][] items,int k){
        Arrays.sort(items,(a,b)->Integer.compare(b[0],a[0]));
        Set<Integer> categories=new HashSet<>();
        PriorityQueue<Integer> duplicates=new PriorityQueue<>();
        long sum=0;
        for(int i=0;i<k;i++){
            sum+=items[i][0];
            if(!categories.add(items[i][1]))duplicates.add(items[i][0]);
        }
        long answer=sum+(long)categories.size()*categories.size();
        for(int i=k;i<items.length&&!duplicates.isEmpty();i++)if(!categories.contains(items[i][1])){
            sum+=items[i][0]-duplicates.poll();
            categories.add(items[i][1]);
            answer=Math.max(answer,sum+(long)categories.size()*categories.size());
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findMaximumElegance(items:Array<IntArray>,k:Int):Long{
        items.sortWith(Comparator{
            a,b->b[0].compareTo(a[0])
        });
        val categories=HashSet<Int>();
        val duplicates=java.util.PriorityQueue<Int>();
        var sum=0L;
        for(i in 0 until k){
            sum+=items[i][0];
            if(!categories.add(items[i][1]))duplicates.add(items[i][0])
        };
        var answer=sum+categories.size.toLong()*categories.size;
        var i=k;
        while(i<items.size&&duplicates.isNotEmpty()){
            if(items[i][1] !in categories){
                sum+=items[i][0]-duplicates.poll();
                categories.add(items[i][1]);
                answer=maxOf(answer,sum+categories.size.toLong()*categories.size)
            };
            i++
        };
        return answer
    }
}

